#pragma once
#include <NexumDesign.h>
#include "Expansion.h"
namespace noctrl {
class OscWaveEditor:public juce::Component {
 SynthProcessor& p;int osc=0,frame=0,last=-1;juce::AudioBuffer<float> waves;juce::TextButton previous{"<"},next{">"},add{"DUPLICATE"},remove{"DELETE"},normalise{"NORMALISE"},invert{"INVERT"},reverse{"REVERSE"},apply{"APPLY"};juce::Label title,status;
 juce::Rectangle<float> plot()const{return {16,49,(float)getWidth()-32,210};}
 void draw(juce::Point<float> point){auto r=plot();int k=juce::jlimit(0,2047,(int)((point.x-r.getX())/r.getWidth()*2047));float value=juce::jlimit(-1.f,1.f,(r.getCentreY()-point.y)/(r.getHeight()*.5f));int from=last<0?k:last;float start=waves.getSample(0,frame*2048+from);for(int i=juce::jmin(from,k);i<=juce::jmax(from,k);++i)waves.setSample(0,frame*2048+i,from==k?value:start+(value-start)*(i-from)/(k-from));last=k;repaint();}
 void commit(){juce::String error;if(p.setOscWavetable(osc,waves,"User Wavetable",error))status.setText("Applied. Included when saving your preset.",juce::dontSendNotification);else status.setText(error,juce::dontSendNotification);}
public:
 OscWaveEditor(SynthProcessor& processor,int which):p(processor),osc(which){using namespace juce;setSize(690,343);auto assets=std::atomic_load(&p.importedAssets);auto* table=assets?assets->tables[osc].get():nullptr;bool useTable=table&&(int)p.value("osc"+String(osc+1)+"bank")==4;int count=useTable?table->frameCount:8;waves.setSize(1,count*2048);for(int f=0;f<count;++f)for(int i=0;i<2048;++i)waves.setSample(0,f*2048+i,useTable?table->data[(size_t)f*mips*(tableSize+1)+i]:p.tables.sample((int)p.value("osc"+String(osc+1)+"bank")==5?4:juce::jmin(3,(int)p.value("osc"+String(osc+1)+"bank")),f/(float)jmax(1,count-1),i/2048.,1,44100));frame=jlimit(0,count-1,roundToInt(p.value("osc"+String(osc+1)+"pos")*(count-1)));addAndMakeVisible(title);title.setBounds(16,7,500,29);title.setText("OSC "+String::charToString('A'+osc)+" / WAVETABLE EDITOR",dontSendNotification);title.setFont(FontOptions(nd::number("fontSize",16),Font::bold));title.setColour(Label::textColourId,nd::colour(Colour(NEXUM_UI_ACCENT)));int x=16;for(auto* button:{&previous,&next,&add,&remove,&normalise,&invert,&reverse,&apply}){addAndMakeVisible(button);int w=button==&previous||button==&next?30:94;button->setBounds(x,273,w,27);x+=w+3;}apply.setBounds(580,306,94,26);addAndMakeVisible(status);status.setBounds(16,305,554,27);status.setFont(FontOptions(nd::number("fontSize",11)));status.setText("Draw to edit; APPLY commits all frames to the sound.",dontSendNotification);
 previous.onClick=[this]{frame=juce::jmax(0,frame-1);repaint();};next.onClick=[this]{frame=juce::jmin(waves.getNumSamples()/2048-1,frame+1);repaint();};add.onClick=[this]{int n=waves.getNumSamples();if(n>=256*2048)return;juce::AudioBuffer<float> copy(waves);waves.setSize(1,n+2048,false,false,true);waves.copyFrom(0,0,copy,0,0,n);waves.copyFrom(0,n,copy,0,frame*2048,2048);frame=n/2048;repaint();};remove.onClick=[this]{int n=waves.getNumSamples();if(n<=2048)return;juce::AudioBuffer<float> copy(waves);waves.setSize(1,n-2048);for(int f=0,k=0;f<n/2048;++f)if(f!=frame)waves.copyFrom(0,k++*2048,copy,0,f*2048,2048);frame=juce::jmin(frame,waves.getNumSamples()/2048-1);repaint();};normalise.onClick=[this]{float peak=waves.getMagnitude(0,frame*2048,2048);if(peak>0)waves.applyGain(0,frame*2048,2048,1/peak);repaint();};invert.onClick=[this]{waves.applyGain(0,frame*2048,2048,-1);repaint();};reverse.onClick=[this]{auto* data=waves.getWritePointer(0,frame*2048);std::reverse(data,data+2048);repaint();};apply.onClick=[this]{commit();};}
 void paint(juce::Graphics& g)override{nd::Scope suitScope("controls");using namespace juce;g.fillAll(UiStyle::canvas());UiStyle::card(g,getLocalBounds().toFloat());UiStyle::header(g,getLocalBounds().toFloat().withHeight(36));auto r=plot();UiStyle::plot(g,r);g.setColour(nd::colour(nd::colour(Colour(0xff344b5d))));g.drawHorizontalLine((int)r.getCentreY(),r.getX(),r.getRight());Path path;for(int i=0;i<2048;++i){float x=r.getX()+i/2047.f*r.getWidth(),y=r.getCentreY()-waves.getSample(0,frame*2048+i)*r.getHeight()*.48f;if(i==0)path.startNewSubPath(x,y);else path.lineTo(x,y);}UiStyle::fillCurve(g,path,r,r.getCentreY());g.setColour(nd::colour(nd::colour(Colour(NEXUM_UI_ACCENT))));g.strokePath(path,PathStrokeType(nd::number("stroke",1.5f)));g.setFont(FontOptions(nd::number("fontSize",11)));g.drawText("FRAME "+String(frame+1)+" / "+String(waves.getNumSamples()/2048),510,9,164,25,Justification::centredRight);}
 void mouseDown(const juce::MouseEvent& e)override{if(e.mods.isPopupMenu()||!plot().contains(e.position))return;last=-1;draw(e.position);}
 void mouseDrag(const juce::MouseEvent& e)override{if(!e.mods.isPopupMenu()&&last>=0)draw(e.position);}
 void mouseUp(const juce::MouseEvent&)override{last=-1;}
};
}
